package local.lito381.server;
import java.nio.file.*;import java.lang.reflect.*;import java.util.*;
/** Exhaustive row/model inventory. Admission, cursor and effect cells remain pending until individually evidenced. */
public final class TargetIntentInventoryProbe {
 static String text(Object value){return String.valueOf(value).replace('\t',' ').replace('\r',' ').replace('\n',' ');}
 static Object component(Object model,String key)throws Exception{for(var c:model.getClass().getRecordComponents())if(c.getName().equals(key)){var m=c.getAccessor();m.setAccessible(true);return m.invoke(model);}return null;}
 static String sourceType(int type){var tags=new ArrayList<String>();if((type&64)!=0)tags.add("damage/compound-review");if((type&16)!=0)tags.add("healing/undead-inversion-review");if((type&32)!=0)tags.add("recovery/compound-review");if((type&4)!=0)tags.add("curse/restrictions-review");if((type&1)!=0)tags.add("probability/negative-or-compound-review");if((type&2)!=0)tags.add("change/buff-or-negative-review");if((type&8)!=0)tags.add("death/corpse-or-compound-review");if((type&128)!=0)tags.add("other/executor-review");return tags.isEmpty()?"unclassified/executor-review":String.join("+",tags);}
 static String flags(int target){if(target==0)return "ME";var tags=new ArrayList<String>();for(int bit:new int[]{1,2,4,8,16,32})if((target&bit)!=0)tags.add(switch(bit){case 1->"PC";case 2->"NPC";case 4->"CLAN";case 8->"PARTY";case 16->"OWN_PET";default->"PLACE";});return String.join("+",tags);}
 public static void main(String[]a)throws Exception{
  var jar=Path.of(a[3]).toRealPath();if(!Path.of(ClientSession.class.getProtectionDomain().getCodeSource().getLocation().toURI()).toRealPath().equals(jar))throw new AssertionError("actual candidate PC metadata, no PC overlay");
  ResourceDatabase.load(ServerConfig.load(Path.of(a[0]),"standard"));var data=TargetIntentInventoryMetadata.rows;if(data.size()!=NativeSkillTargetMetadata.size())throw new AssertionError("same startup static row snapshot");
  var factories=Arrays.stream(BattleSpellCatalog.class.getDeclaredMethods()).filter(m->Modifier.isStatic(m.getModifiers())&&Arrays.equals(m.getParameterTypes(),new Class<?>[]{int.class})&&m.getReturnType().isRecord()&&m.getReturnType().getSimpleName().endsWith("Spell")).sorted(Comparator.comparing(Method::getName)).toList();var nativeMethods=Arrays.stream(ClientSession.class.getDeclaredMethods()).toList();var rows=new ArrayList<String>();rows.add("skill_id\tname\tsource_type\tclassification_review\ttarget\ttarget_to\ttarget_flags\trange\tarea\tthrough\tskill_level\tskill_number\tnative_id\taction_id\tcastgfx\tnative_models\tnative_entry_locators\tlayout_locators\tself_normal_Ctrl\tfriendly_normal_Ctrl\tenemy_player_normal_Ctrl\tNPC_ArenaBot\town_other_pet_summon\tcorpse_equipment_special\tclient_evidence\tserver_evidence\tresult_or_gap");int models=0,covered=0,matching=0;var matches=new ArrayList<String>();
  for(var row:data.values()){
   var modelNames=new ArrayList<String>();var roots=new TreeSet<String>();var layouts=new TreeSet<String>();
   for(var f:factories){f.setAccessible(true);Object model;try{model=f.invoke(null,row.id());}catch(InvocationTargetException error){continue;}if(model==null||!Objects.equals(component(model,"skillId"),row.id()))continue;models++;modelNames.add(f.getName()+":"+model.getClass().getSimpleName());for(var m:nativeMethods)if((m.getName().startsWith("use")||m.getName().startsWith("nativeMaterial")||m.getName().startsWith("nativeArea"))&&Arrays.asList(m.getParameterTypes()).contains(model.getClass()))roots.add(m.getName());for(String field:List.of("requestShape","requestLayout","lineTargeted")){var value=component(model,field);if(value!=null)layouts.add(field+"="+value);}}
   if(!modelNames.isEmpty())covered++;boolean example=row.name().contains("通暢氣脈");if(example){matching++;matches.add(row.id()+"\t"+row.name()+"\t"+modelNames+"\t"+flags(row.targetTo()));}
   String gap=modelNames.isEmpty()?"native executor/model locator absent; Source/player/NPC applicability must be reviewed":"per-skill Source restrictions, packet/root reachability, cursor and role/effect evidence pending";
   rows.add(String.join("\t",List.of(""+row.id(),text(row.name()),""+row.type(),sourceType(row.type()),row.target(),""+row.targetTo(),flags(row.targetTo()),""+row.range(),""+row.area(),""+row.through(),""+row.level(),""+row.number(),""+row.nativeId(),""+row.action(),""+row.gfx(),text(modelNames),text(roots),text(layouts),"legal-source-target only: normal allowed; Ctrl cannot widen skill kind [pending]","legal-source/faction relation only: assistance normal allowed; other cases Source review [pending]","explicit hostile player intent required; normal reject / Ctrl conditional [new policy pending]","Source kind/life/range/LOS/immune rules; no blanket Ctrl [pending]","own/other ownership and Source class rules [pending]","item/corpse/self/place/selector layouts require individual classification [pending]","no fresh cursor/wire evidence","static candidate locators only; no admission/effect qualification",gap)));
  }
  Files.write(Path.of(a[1]),rows);Files.write(Path.of(a[1]).resolveSibling("reported-skill-name-matches.tsv"),matches);Files.writeString(Path.of(a[2]),"{\"static_skill_rows\":"+data.size()+",\"native_factory_model_records\":"+models+",\"native_model_located_skill_ids\":"+covered+",\"reported_name_matches\":"+matching+",\"native_runtime_cases\":0,\"all_target_intent_policy_qualified\":false,\"full_goal_achieved\":false}\n");
 }
}
